import { t as building } from "../chunks/environment.js";
import { n as authorize } from "../chunks/access.js";
import { t as connectDB } from "../chunks/db.js";
import { t as broadcastManager } from "../chunks/broadcast.js";
import { n as initCron } from "../chunks/cron.js";
import { json } from "@sveltejs/kit";
//#region src/hooks.server.js
if (!building && !global.cronInitialized) {
	initCron();
	global.cronInitialized = true;
	console.log("✅ Cron Engine: Inicializado (Instancia Única)");
}
if (!building) broadcastManager.rehydrate().catch((err) => console.error("❌ Andon: fallo en la rehidratación inicial:", err));
var handle = async ({ event, resolve }) => {
	const { pathname } = event.url;
	const session = event.cookies.get("session_id");
	if (session) try {
		const user = await (await connectDB()).collection("USERS").findOne({ sessionToken: session });
		if (user) {
			const { password, _id, ...safeUser } = user;
			event.locals.user = {
				...safeUser,
				id: _id.toString()
			};
		} else event.locals.user = null;
	} catch (error) {
		console.error("❌ Error de sesión en Hooks:", error);
		event.locals.user = null;
	}
	else event.locals.user = null;
	const decision = authorize(pathname, event.locals.user);
	const isApi = pathname.startsWith("/api/");
	if (decision === "LOGIN") {
		if (isApi) return json({
			success: false,
			error: "Authentication required"
		}, { status: 401 });
		return new Response(null, {
			status: 303,
			headers: { location: "/login" }
		});
	}
	if (decision === "FORBIDDEN") {
		if (isApi) return json({
			success: false,
			error: "Insufficient permissions"
		}, { status: 403 });
		return new Response("403 Forbidden: Insufficient permissions", {
			status: 403,
			headers: { "Content-Type": "text/plain; charset=utf-8" }
		});
	}
	return await resolve(event);
};
//#endregion
export { handle };
